import {$,el,project,api,money} from './quote-view.mjs';
import {sample} from './quote-demo.mjs';
const demo=new URLSearchParams(location.search).get('demo')==='1';let page=0,current=null,example=structuredClone(sample),loadVersion=0;
if(demo){$('demo-notice').hidden=false;$('staff-signout').hidden=true;}
const message=text=>{$('inbox-message').textContent=text;};
function renderDetail(data){current=data;$('quote-detail').hidden=false;$('detail-id').textContent=data.id;$('detail-date').textContent=new Date(data.createdAt).toLocaleString();const c=data.payload.contact;$('customer').replaceChildren(el('h3',c.name),el('p',c.company||'No company supplied'));
 for(const [label,href]of [[c.phone,'tel:'+c.phone.replace(/[^+\d]/g,'')],[c.email,'mailto:'+c.email]]){const a=el('a',label);a.href=href;$('customer').append(a);}
 $('customer-notes').textContent=data.payload.notes||'No additional notes.';project(data,$('detail-project'));$('edit-status').value=data.status;$('internal-notes').value=data.internalNotes;$('notify-state').textContent=`Email notification: ${data.notification==='accepted'?'accepted by email provider (delivery not verified)':data.notification.replaceAll('_',' ')}`;$('retry-notify').disabled=data.notification==='accepted';$('edit-message').textContent='';
 $('customer-notify-state').textContent=`Customer confirmation email: ${data.customerNotification||'demo'}`;const linkActive=!data.receiptRevoked&&Date.parse(data.receiptExpiresAt)>Date.now();$('customer-link-state').textContent=data.receiptRevoked?'Customer link disabled.':data.receiptExpiresAt?`Customer link expires ${new Date(data.receiptExpiresAt).toLocaleString()}.`:'Example link lasts 30 days.';$('revoke-receipt').disabled=demo||!linkActive;$('retry-customer').disabled=demo||!linkActive||data.customerNotification==='accepted';
}
async function openQuote(id){const version=++loadVersion;message('Loading request…');try{const data=demo?structuredClone(example):await api('/api/staff/quotes/'+encodeURIComponent(id));if(version!==loadVersion)return;renderDetail(data);message('');const u=new URL(location);u.searchParams.set('id',id);history.replaceState(null,'',u);$('detail-id').focus();}catch(e){if(version===loadVersion)message(e.message);}}
async function load(){message('Loading quote requests…');$('quote-list').replaceChildren();try{
 const q=$('quote-search').value,status=$('status-filter').value;
 const data=demo?{quotes:[example].filter(r=>(!status||r.status===status)&&(!q||JSON.stringify([r.id,r.payload.contact.name,r.payload.address]).toLowerCase().includes(q.toLowerCase()))).map(r=>({...r,name:r.payload.contact.name,address:r.payload.address})),hasMore:false}:await api('/api/staff/quotes?'+new URLSearchParams({q,status,page}));
 for(const r of data.quotes){const button=el('button',undefined,'quote-list-item');button.type='button';button.append(el('span',r.id,'reference'),el('strong',r.name),el('span',r.address),el('span',`${r.status.charAt(0).toUpperCase()+r.status.slice(1)} · ${money(r.pricing.total)}`,'quiet'),el('small',new Date(r.createdAt).toLocaleDateString()));button.onclick=()=>openQuote(r.id);$('quote-list').append(button);}
 $('previous-page').disabled=page===0;$('next-page').disabled=!data.hasMore;$('page-number').textContent=`Page ${page+1}`;message(data.quotes.length?'':'No quote requests match this search.');
 }catch(error){message(error.message);}}
$('search-form').onsubmit=e=>{e.preventDefault();page=0;load();};$('status-filter').onchange=()=>{page=0;load();};$('previous-page').onclick=()=>{page--;load();};$('next-page').onclick=()=>{page++;load();};
$('quote-edit').onsubmit=async e=>{e.preventDefault();if(!current)return;const button=$('save-quote');button.disabled=true;const update={status:$('edit-status').value,internalNotes:$('internal-notes').value,revision:current.revision};try{if(demo){Object.assign(example,{...update,revision:example.revision+1});renderDetail(structuredClone(example));$('edit-message').textContent='Demo update only — resets when you reload.';}else{const updated=await api('/api/staff/quotes/'+current.id,{method:'PATCH',body:JSON.stringify(update)});renderDetail(updated);$('edit-message').textContent='Changes saved.';}await load();}catch(error){$('edit-message').textContent=error.message;}finally{button.disabled=false;}};
$('retry-notify').onclick=async()=>{if(!current)return;$('retry-notify').disabled=true;try{if(demo){$('edit-message').textContent='Demo only — no email sent.';return;}renderDetail(await api('/api/staff/quotes/'+current.id+'/notify',{method:'POST',body:'{}'}));}catch(e){$('edit-message').textContent=e.message;}finally{$('retry-notify').disabled=current?.notification==='accepted';}};
$('print-quote').onclick=()=>window.print();
$('download-quote').onclick=()=>{if(!current)return;const blob=new Blob([JSON.stringify(current,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=el('a');a.href=url;a.download=current.id+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
load().then(()=>{const id=new URLSearchParams(location.search).get('id');if(id)openQuote(id);else if(demo)openQuote(example.id);});

for(const [button,route]of [['retry-customer','customer-notify'],['revoke-receipt','revoke-receipt']])$(button).onclick=async()=>{if(!current||demo)return;$(button).disabled=true;try{renderDetail(await api('/api/staff/quotes/'+current.id+'/'+route,{method:'POST',body:'{}'}));$('edit-message').textContent=route==='revoke-receipt'?'Customer link disabled. The saved request is unchanged.':'Customer email status updated.';}catch(error){$('edit-message').textContent=error.message;$(button).disabled=false;}};
